  add([0]);
  add([5]);
  add([-1]);
  add([1, 2, 3]);
  add([4, 4, 4, 4]);
  add([1, 1, 2, 3]);
  add([1, 2, 3, 3]);
  add([-3, -3, -1, 0, 0, 2]);
