export async function gate({ referenceDir, submissionDir }) {
  const cases = makeCases();
  const cookie = crypto.randomBytes(32).toString('hex');
  const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'gate-'));
  const harnessPath = path.join(tmpDir, 'harness.mjs');
  const outputPath = path.join(tmpDir, 'output.json');
  const casesPath = path.join(tmpDir, 'cases.json');
  const submissionPath = path.join(submissionDir, 'answer.mjs');

  fs.writeFileSync(casesPath, JSON.stringify(cases));

  const harnessSrc = [
    "import fs from 'node:fs';",
    "import { pathToFileURL } from 'node:url';",
    'const realExit = process.exit.bind(process);',
    'process.exit = () => {};',
    'try { process.abort = () => {}; } catch (e) {}',
    'const cases = JSON.parse(fs.readFileSync(' + JSON.stringify(casesPath) + ', "utf8"));',
    'const submissionPath = ' + JSON.stringify(submissionPath) + ';',
    'const outputPath = ' + JSON.stringify(outputPath) + ';',
    'const cookie = ' + JSON.stringify(cookie) + ';',
    'function finish(payload) { try { fs.writeFileSync(outputPath, JSON.stringify(payload)); } catch (e) {} }',
    'try {',
    '  const mod = await import(pathToFileURL(submissionPath).href);',
    '  const fn = mod && mod.dedupeSorted;',
    "  if (typeof fn !== 'function') { finish({ cookie, error: 'dedupeSorted not a function' }); realExit(0); }",
    '  else {',
    '    const results = [];',
    '    for (let i = 0; i < cases.length; i++) {',
    '      try {',
    '        const copy = Array.isArray(cases[i]) ? cases[i].slice() : cases[i];',
    '        const raw = fn(copy);',
    '        let output;',
    "        try { output = JSON.parse(JSON.stringify(raw)); } catch (e) { results.push({ i, error: 'unserializable' }); continue; }",
    '        results.push({ i, output });',
    '      } catch (err) {',
    '        results.push({ i, error: String(err && err.message ? err.message : err) });',
    '      }',
    '    }',
    '    finish({ cookie, results });',
    '  }',
    '} catch (err) { finish({ cookie, error: String(err && err.stack ? err.stack : err) }); }',
    'realExit(0);',
  ].join('\n');

  fs.writeFileSync(harnessPath, harnessSrc, 'utf8');

  const outcome = await new Promise((resolve) => {
    const child = spawn(process.execPath, [harnessPath], {
      stdio: ['ignore', 'ignore', 'ignore'],
      cwd: tmpDir,
      env: { NO_COLOR: '1' },
    });
    let settled = false;
    const timer = setTimeout(() => {
      if (settled) return;
      settled = true;
      try { child.kill('SIGKILL'); } catch (e) {}
      resolve({ timeout: true });
    }, 12000);
    child.on('close', (code, signal) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      resolve({ timeout: false, code, signal });
    });
    child.on('error', () => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      resolve({ timeout: false, error: true });
    });
  });

  const cleanup = () => { try { fs.rmSync(tmpDir, { recursive: true, force: true }); } catch (e) {} };

  if (outcome.timeout) { cleanup(); return { accept: false, reason: 'test suite timed out' }; }
  if (outcome.error) { cleanup(); return { accept: false, reason: 'failed to launch test child' }; }
  if (outcome.code !== 0) { cleanup(); return { accept: false, reason: 'test child exited abnormally' }; }
  if (!fs.existsSync(outputPath)) { cleanup(); return { accept: false, reason: 'no result written' }; }

  let payload;
  try { payload = JSON.parse(fs.readFileSync(outputPath, 'utf8')); }
  catch (e) { cleanup(); return { accept: false, reason: 'unreadable result' }; }

  if (payload.cookie !== cookie) { cleanup(); return { accept: false, reason: 'cookie mismatch' }; }
  if (payload.error || !Array.isArray(payload.results)) {
    cleanup();
    return { accept: false, reason: String(payload.error || 'missing results') };
  }
  if (payload.results.length !== cases.length) {
    cleanup();
    return { accept: false, reason: 'incomplete suite' };
  }

  const failures = [];
  for (let i = 0; i < cases.length; i++) {
    const r = payload.results[i];
    if (!r || r.i !== i) { failures.push('index ' + i); continue; }
    if (r.error) { failures.push('threw on ' + JSON.stringify(cases[i])); continue; }
    const exp = expectedDedupe(cases[i]);
    if (!eq(r.output, exp)) {
      failures.push(JSON.stringify(cases[i]) + ' -> ' + JSON.stringify(r.output) + ' expected ' + JSON.stringify(exp));
    }
  }
  cleanup();
  if (failures.length) {
    return { accept: false, reason: failures.length + ' failure(s): ' + failures.slice(0, 3).join('; ') };
  }
  return { accept: true, reason: 'all ' + cases.length + ' cases passed' };
}

